mapper.update:
UPDATE nw_model_realtime_sessions SET next_audio_sequence=next_audio_sequence+1,updated_at=#{at}
WHERE id=CAST(#{id} AS bigint) AND owner_id=#{owner} AND next_audio_sequence=#{sequence}
  AND status='RUNNING' AND NOT finishing AND deadline>#{at}

UPDATE nw_model_realtime_sessions SET asset_available=TRUE,asset_media_type=#{assetMediaType},asset_name=#{assetName},
  asset_size_bytes=#{assetSizeBytes},asset_sha256=#{assetSha256},updated_at=#{updatedAt}
WHERE id=CAST(#{id} AS bigint) AND asset_id=CAST(#{assetId} AS bigint) AND NOT asset_available
